#!/usr/bin/env python3
"""Exercise production browser ownership against Android API boundaries, without a device."""
import pathlib, subprocess, tempfile
ROOT=pathlib.Path(__file__).resolve().parents[1]
SOURCE=ROOT/'src/dev/dsh/nativeapp'
if not SOURCE.is_dir(): SOURCE=ROOT/'bootstrap/src/dev/dsh/nativeapp'
STUBS={
'android/content/Context.java':'package android.content;public class Context {}',
'android/view/ViewGroup.java':'package android.view;public class ViewGroup {public int removed;public void removeView(Object v){removed++;}}',
'android/webkit/WebSettings.java':"""package android.webkit;public class WebSettings {public boolean js,storage,wide,overview,zoom,builtin,controls;public int text;
public void setJavaScriptEnabled(boolean v){js=v;}public void setDomStorageEnabled(boolean v){storage=v;}public void setAllowFileAccess(boolean v){}public void setUseWideViewPort(boolean v){wide=v;}public void setLoadWithOverviewMode(boolean v){overview=v;}public void setSupportZoom(boolean v){zoom=v;}public void setBuiltInZoomControls(boolean v){builtin=v;}public void setDisplayZoomControls(boolean v){controls=v;}public void setTextZoom(int v){text=v;}}""",
'android/webkit/WebView.java':"""package android.webkit;public class WebView {public static int created;public int backgrounds,navigations,resumes,pauses,stops,detached,cleared,destroys;public String script,url;public boolean failStop;public android.view.ViewGroup parent=new android.view.ViewGroup();public final WebSettings settings=new WebSettings();public WebView(android.content.Context c){created++;}public void setBackgroundColor(int c){backgrounds++;}public WebSettings getSettings(){return settings;}public void setInitialScale(int s){}public void loadUrl(String u){url=u;navigations++;}public void evaluateJavascript(String s,Object c){script=s;}public void onResume(){resumes++;}public void onPause(){pauses++;}public void stopLoading(){stops++;if(failStop)throw new IllegalStateException("injected renderer failure");}public void setWebChromeClient(Object c){detached++;}public void setWebViewClient(Object c){detached++;}public Object getParent(){return parent;}public void removeAllViews(){cleared++;}public void destroy(){destroys++;}}""",
'dev/dsh/nativeapp/BrowserProbe.java':"""package dev.dsh.nativeapp;import android.webkit.*;
public class BrowserProbe {static int checks;static void check(boolean yes,String why){if(!yes)throw new AssertionError(why);checks++;}public static void main(String[] a){WebSession session=new WebSession(new android.content.Context(),115,0);WebView page=session.view();check(page.settings.js&&page.settings.storage&&page.settings.wide&&page.settings.overview&&page.settings.zoom&&page.settings.builtin&&!page.settings.controls&&page.settings.text==115,"one common browser configuration");session.navigate("http://127.0.0.1:3080/");check(page.navigations==1,"explicit navigation only");for(int i=0;i<100;i++){session.viewport(i%2==0?436:1200);session.pause();session.resume();}check(session.view()==page&&WebView.created==1&&page.navigations==1,"viewport and foreground cycles retain exactly one document");check(page.pauses==100&&page.resumes==100&&page.script.contains("dsh-native-resume"),"resume informs the original DSH connection service");session.close();check(session.view()==null&&page.destroys==1&&page.detached==2&&page.parent.removed==1&&page.cleared==1,"close releases renderer, clients and hierarchy");session.close();session.resume();session.viewport(480);session.navigate("ignored");check(page.destroys==1&&page.navigations==1,"closed browser never revives");WebSession broken=new WebSession(new android.content.Context(),100,0);page=broken.view();page.failStop=true;try{broken.close();throw new AssertionError("cleanup failure hidden");}catch(IllegalStateException expected){check(page.destroys==1&&page.detached==2&&page.parent.removed==1,"renderer failure cannot skip remaining cleanup");}System.out.println("Web session: "+checks+" production configuration, retained navigation, 100 foreground/viewport cycles and cleanup checks passed; Android boundaries only.");}}"""}
with tempfile.TemporaryDirectory(prefix='dsh-web-session-') as directory:
 root=pathlib.Path(directory)
 for name,body in STUBS.items():
  p=root/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(body)
 files=['WebSession','ViewportState','MobileLayout','SessionProbe','SessionStatus','ConnectionRecovery','DraftRecovery']
 subprocess.run(['javac','--release','8','-encoding','UTF-8','-d',str(root/'classes'),*map(str,root.rglob('*.java')),*[str(SOURCE/(f+'.java')) for f in files]],check=True)
 subprocess.run(['java','-cp',str(root/'classes'),'dev.dsh.nativeapp.BrowserProbe'],check=True)
